const Logout = () => {
    let navigate = useNavigate();

    const out = useCallback(() => {
        localStorage.clear();
        setTimeout(()=>navigate("/"),500
        );
        localStorage.clear();
    }, [navigate]);

    useEffect(() => {
        out();
    }, [out]);
    return null;
}

